// Generated by AI QA Agent from .qa/scenarios/contact.json — regenerated when scenarios change.
import { test, expect, type Page, type Locator } from '@mohammadvazifedoost/ai-qa-agent/playwright';

const NAME_ERROR = 'Enter your name';
const EMAIL_ERROR = 'Enter a valid email address';
const SENT_HEADING = 'Message sent';
const FORM_HEADING = 'Contact us';
const NAME = 'Ada Lovelace';
const EMAIL = 'ada@example.com';
const THANKS = 'Thanks Ada Lovelace, we reply within two working days.';

// Local page helpers -------------------------------------------------------

function form(page: Page): Locator {
  return page.getByRole('form', { name: 'Contact' });
}

function nameInput(page: Page): Locator {
  return page.getByLabel('Name', { exact: true });
}

function emailInput(page: Page): Locator {
  return page.getByLabel('Email', { exact: true });
}

function messageInput(page: Page): Locator {
  return page.getByLabel('Message', { exact: true });
}

// The form contains a single button; its name toggles between 'Send message' and 'Sending…'.
function submitButton(page: Page): Locator {
  return form(page).getByRole('button');
}

function heading(page: Page, name: string): Locator {
  return page.getByRole('heading', { level: 1, name, exact: true });
}

function mainNav(page: Page): Locator {
  return page.getByRole('navigation', { name: 'Main' });
}

function navLink(page: Page, name: string): Locator {
  return mainNav(page).getByRole('link', { name, exact: true });
}

async function openContact(page: Page) {
  await page.goto('/contact');
  await expect(heading(page, FORM_HEADING)).toBeVisible();
}

async function fillForm(page: Page, name: string, email: string, message?: string) {
  await nameInput(page).fill(name);
  await emailInput(page).fill(email);
  if (message !== undefined) await messageInput(page).fill(message);
}

async function submit(page: Page) {
  await submitButton(page).click();
}

async function expectNoFieldErrors(page: Page) {
  await expect(page.getByText(NAME_ERROR, { exact: true })).toHaveCount(0);
  await expect(page.getByText(EMAIL_ERROR, { exact: true })).toHaveCount(0);
}

async function expectSent(page: Page) {
  await expect(heading(page, SENT_HEADING)).toBeVisible();
  await expect(page.getByText(THANKS, { exact: true })).toBeVisible();
  await expect(form(page)).toHaveCount(0);
}

async function box(locator: Locator) {
  const b = await locator.boundingBox();
  expect(b, 'element should have a bounding box').not.toBeNull();
  return b!;
}

// An error is announced when it is a role=alert element or is referenced through aria-describedby.
async function expectErrorAnnounced(page: Page, input: Locator, message: string) {
  const alerts = await page.getByRole('alert').filter({ hasText: message }).count();
  const describedBy = await input.getAttribute('aria-describedby');
  let described = false;
  if (describedBy) {
    const text = await page.locator(`[id="${describedBy}"]`).textContent();
    described = (text ?? '').trim() === message;
  }
  expect(
    alerts > 0 || described,
    `error '${message}' should be exposed via role="alert" or aria-describedby`,
  ).toBe(true);
}

// Tests --------------------------------------------------------------------

test.describe('/contact', () => {
  test(
    'CONTACT-001: Send a contact message with valid data shows confirmation',
    { tag: ['@functional', '@contact', '@desktop', '@high'] },
    async ({ page }) => {
      await test.step('Open /', async () => {
        await page.goto('/');
        await expect(navLink(page, 'Contact')).toBeVisible();
      });

      await test.step("Click nav link 'Contact' in the 'Main' navigation", async () => {
        await navLink(page, 'Contact').click();
        await expect(page).toHaveURL(/\/contact$/);
      });

      await test.step("Verify h1 'Contact us' and the form fields are visible", async () => {
        await expect(heading(page, FORM_HEADING)).toBeVisible();
        await expect(form(page)).toBeVisible();
        await expect(nameInput(page)).toBeVisible();
        await expect(emailInput(page)).toBeVisible();
        await expect(messageInput(page)).toBeVisible();
      });

      await test.step("'Contact' nav link is visually marked as active", async () => {
        const contact = navLink(page, 'Contact');
        await expect(contact).toHaveClass(/\bactive\b/);
        await expect(contact).toHaveAttribute('aria-current', 'page');
        const contactColor = await contact.evaluate((el) => getComputedStyle(el).color);
        const homeColor = await navLink(page, 'Home').evaluate((el) => getComputedStyle(el).color);
        expect(contactColor, 'active link colour differs from an inactive link').not.toBe(homeColor);
      });

      await test.step("Fill 'Name', 'Email' and 'Message'", async () => {
        await nameInput(page).fill(NAME);
        await emailInput(page).fill(EMAIL);
        await messageInput(page).fill('Hello, I have a question about my order.');
      });

      await test.step("Click 'Send message'", async () => {
        await submit(page);
      });

      await test.step('Confirmation is shown and the form is gone', async () => {
        await expect(heading(page, SENT_HEADING)).toBeVisible();
        await expect(form(page)).toHaveCount(0);
        await expect(page.getByText(THANKS, { exact: true })).toBeVisible();
        await expectNoFieldErrors(page);
        await expect(page).toHaveURL(/\/contact$/);
      });
    },
  );

  test(
    'CONTACT-002: Submitting an empty form shows both required-field errors and sends nothing',
    { tag: ['@functional', '@contact', '@desktop', '@high'] },
    async ({ page }) => {
      await test.step('Open /contact', async () => {
        await openContact(page);
      });

      await test.step("Leave all fields empty and click 'Send message'", async () => {
        await submit(page);
      });

      await test.step('Both errors are visible at the same time', async () => {
        await expect(page.getByText(NAME_ERROR, { exact: true })).toBeVisible();
        await expect(page.getByText(EMAIL_ERROR, { exact: true })).toBeVisible();
      });

      await test.step("Errors are shown under their fields and inputs are marked invalid", async () => {
        const nameBox = await box(nameInput(page));
        const nameErr = await box(page.getByText(NAME_ERROR, { exact: true }));
        expect(nameErr.y).toBeGreaterThanOrEqual(nameBox.y + nameBox.height);
        const emailBox = await box(emailInput(page));
        const emailErr = await box(page.getByText(EMAIL_ERROR, { exact: true }));
        expect(emailErr.y).toBeGreaterThanOrEqual(emailBox.y + emailBox.height);

        await expect(nameInput(page)).toHaveAttribute('aria-invalid', 'true');
        await expect(emailInput(page)).toHaveAttribute('aria-invalid', 'true');
      });

      await test.step('Nothing is sent: heading, form and button unchanged', async () => {
        await expect(heading(page, FORM_HEADING)).toBeVisible();
        await expect(form(page)).toBeVisible();
        await expect(heading(page, SENT_HEADING)).toHaveCount(0);
        await expect(submitButton(page)).toHaveText('Send message');
        await expect(submitButton(page)).toBeEnabled();
      });
    },
  );

  test(
    'CONTACT-003: Whitespace-only name is rejected',
    { tag: ['@functional', '@contact', '@desktop', '@high'] },
    async ({ page }) => {
      await test.step('Open /contact', async () => {
        await openContact(page);
      });

      await test.step("Fill 'Name' with three spaces and 'Email' with a valid address", async () => {
        await fillForm(page, '   ', EMAIL);
      });

      await test.step("Click 'Send message'", async () => {
        await submit(page);
      });

      await test.step('Only the name error is shown and the form stays visible', async () => {
        await expect(page.getByText(NAME_ERROR, { exact: true })).toBeVisible();
        await expect(page.getByText(EMAIL_ERROR, { exact: true })).toHaveCount(0);
        await expect(emailInput(page)).not.toHaveAttribute('aria-invalid', 'true');
        await expect(form(page)).toBeVisible();
        await expect(heading(page, FORM_HEADING)).toBeVisible();
        await expect(heading(page, SENT_HEADING)).toHaveCount(0);
      });
    },
  );

  test(
    'CONTACT-004: Malformed email addresses are rejected, minimal valid address accepted',
    { tag: ['@functional', '@contact', '@desktop', '@high'] },
    async ({ page }) => {
      await test.step("Open /contact and fill 'Name'", async () => {
        await openContact(page);
        await nameInput(page).fill(NAME);
      });

      const invalid = ['not-an-email', 'a@b', 'a b@c.d'];

      for (const email of invalid) {
        await test.step(`Submit invalid email '${email}'`, async () => {
          await emailInput(page).fill(email);
          await submit(page);

          await expect(page.getByText(EMAIL_ERROR, { exact: true })).toBeVisible();
          await expect(emailInput(page)).toHaveAttribute('aria-invalid', 'true');
          await expect(page.getByText(NAME_ERROR, { exact: true })).toHaveCount(0);
          await expect(form(page)).toBeVisible();
          await expect(heading(page, SENT_HEADING)).toHaveCount(0);

          // The form has no native validation bubble: the browser must not flag the field as invalid-blocking submit
          const nativeBlocked = await form(page).evaluate((el) => (el as HTMLFormElement).noValidate);
          expect(nativeBlocked, 'form uses noValidate so only the custom message is shown').toBe(true);
        });
      }

      await test.step("Submit the minimal valid email 'a@b.c'", async () => {
        await emailInput(page).fill('a@b.c');
        await submit(page);
        await expectSent(page);
        await expect(page.getByText(EMAIL_ERROR, { exact: true })).toHaveCount(0);
      });
    },
  );

  test(
    'CONTACT-005: Message is optional and the confirmation greets the trimmed name',
    { tag: ['@functional', '@contact', '@desktop', '@medium'] },
    async ({ page }) => {
      await test.step('Open /contact', async () => {
        await openContact(page);
      });

      await test.step("Fill 'Name' with padded value and 'Email'; leave 'Message' empty", async () => {
        await fillForm(page, '  Ada Lovelace  ', EMAIL);
        await expect(messageInput(page)).toHaveValue('');
      });

      await test.step("Click 'Send message'", async () => {
        await submit(page);
      });

      await test.step('No validation error and the trimmed-name confirmation is shown', async () => {
        await expect(heading(page, SENT_HEADING)).toBeVisible();
        await expectNoFieldErrors(page);
        await expect(page.getByText(THANKS, { exact: true })).toBeVisible();
        const text = await page.getByText(/^Thanks .*we reply within two working days\.$/).textContent();
        expect(text).toBe(THANKS);
      });
    },
  );

  test(
    'CONTACT-006: Sending state disables the button and prevents double submit',
    { tag: ['@functional', '@contact', '@desktop', '@medium'] },
    async ({ page }) => {
      await test.step("Open /contact and fill 'Name' and 'Email'", async () => {
        await openContact(page);
        await fillForm(page, NAME, EMAIL);
      });

      await test.step("Click 'Send message' and immediately inspect the button", async () => {
        await submit(page);
        const button = submitButton(page);
        await expect(button).toHaveText('Sending…');
        await expect(button).toBeDisabled();
        await expect(button).not.toHaveCSS('opacity', '1');
      });

      await test.step('Clicking the disabled button again does nothing', async () => {
        // A native click on a disabled button dispatches no click event; no second submission occurs.
        await submitButton(page)
          .evaluate((el) => (el as HTMLButtonElement).click())
          .catch(() => {
            // The form may already have been replaced by the confirmation; that is fine.
          });
      });

      await test.step('After completion the confirmation is shown once and the form is removed', async () => {
        await expect(heading(page, SENT_HEADING)).toBeVisible();
        await expect(heading(page, SENT_HEADING)).toHaveCount(1);
        await expect(page.getByText(THANKS, { exact: true })).toHaveCount(1);
        await expect(form(page)).toHaveCount(0);
      });
    },
  );

  test(
    'CONTACT-007: Form is accessible by keyboard and errors are correctable and announced',
    { tag: ['@functional', '@contact', '@desktop', '@medium'] },
    async ({ page }) => {
      await test.step('Open /contact', async () => {
        await openContact(page);
      });

      await test.step('Each label focuses its own field', async () => {
        for (const [label, control] of [
          ['Name', nameInput(page)],
          ['Email', emailInput(page)],
          ['Message', messageInput(page)],
        ] as const) {
          await page.locator('label', { hasText: new RegExp(`^${label}$`) }).click();
          await expect(control).toBeFocused();
        }
      });

      await test.step("Tab from the page start until 'Name' is focused", async () => {
        await page.reload();
        await expect(heading(page, FORM_HEADING)).toBeVisible();
        for (let i = 0; i < 20; i++) {
          if (await nameInput(page).evaluate((el) => el === document.activeElement)) break;
          await page.keyboard.press('Tab');
        }
        await expect(nameInput(page)).toBeFocused();
      });

      await test.step("Tab to 'Email' and type 'bad'", async () => {
        await page.keyboard.press('Tab');
        await expect(emailInput(page)).toBeFocused();
        await page.keyboard.type('bad');
        await expect(emailInput(page)).toHaveValue('bad');
      });

      await test.step('Press Enter to submit while focus is in Email', async () => {
        await page.keyboard.press('Enter');
        await expect(page.getByText(NAME_ERROR, { exact: true })).toBeVisible();
        await expect(page.getByText(EMAIL_ERROR, { exact: true })).toBeVisible();
      });

      await test.step('Errors are exposed to assistive technology and fields are aria-invalid', async () => {
        await expect(nameInput(page)).toHaveAttribute('aria-invalid', 'true');
        await expect(emailInput(page)).toHaveAttribute('aria-invalid', 'true');
        await expectErrorAnnounced(page, nameInput(page), NAME_ERROR);
        await expectErrorAnnounced(page, emailInput(page), EMAIL_ERROR);
      });

      await test.step("Correct 'Name' and 'Email'", async () => {
        await nameInput(page).fill(NAME);
        await emailInput(page).fill(EMAIL);
      });

      await test.step("Tab to 'Send message' and press Enter", async () => {
        await page.keyboard.press('Tab'); // Message
        await expect(messageInput(page)).toBeFocused();
        await page.keyboard.press('Tab'); // Send message
        await expect(submitButton(page)).toBeFocused();
        await page.keyboard.press('Enter');
      });

      await test.step('Errors disappear and the confirmation is shown', async () => {
        await expect(heading(page, SENT_HEADING)).toBeVisible();
        await expectNoFieldErrors(page);
      });
    },
  );

  test(
    "CONTACT-008: 'Send message' button and inputs match Figma Button/Input specs",
    { tag: ['@visual', '@contact', '@desktop', '@high'] },
    async ({ page, qa }) => {
      await test.step('Open /contact at desktop viewport', async () => {
        await openContact(page);
      });

      await test.step("Inspect the 'Send message' button", async () => {
        await expect(submitButton(page)).toHaveText('Send message');
        await qa.expectDesignTokens(
          submitButton(page),
          {
            backgroundColor: '#2563EB',
            color: '#FFFFFF',
            borderRadius: '8px',
            height: '44px',
            paddingLeft: '20px',
            paddingRight: '20px',
            fontFamily: 'Inter',
            fontSize: '16px',
            fontWeight: '600',
            lineHeight: '24px',
          },
          "'Send message' button",
        );
      });

      await test.step("Inspect the 'Name' and 'Email' inputs", async () => {
        await qa.expectDesignTokens(nameInput(page), { height: '44px' }, "'Name' input");
        await qa.expectDesignTokens(emailInput(page), { height: '44px' }, "'Email' input");
      });
    },
  );

  test(
    'CONTACT-009: Contact form is usable at mobile width without horizontal overflow',
    { tag: ['@responsive', '@contact', '@mobile', '@medium'] },
    async ({ page, qa }) => {
      const VIEWPORT_WIDTH = 390;
      const GUTTER = 24;

      await test.step('Open /contact at mobile viewport', async () => {
        await openContact(page);
        await expect(nameInput(page)).toBeVisible();
        await expect(emailInput(page)).toBeVisible();
        await expect(messageInput(page)).toBeVisible();
      });

      await test.step('No horizontal scrolling', async () => {
        await qa.expectNoHorizontalOverflow();
        const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
        expect(scrollWidth).toBe(VIEWPORT_WIDTH);
      });

      await test.step('Fields are stacked with a 24px gutter and fit the viewport', async () => {
        const name = await box(nameInput(page));
        const email = await box(emailInput(page));
        const message = await box(messageInput(page));
        const button = await box(submitButton(page));

        for (const control of [name, email, message, button]) {
          expect(control.x).toBeGreaterThanOrEqual(GUTTER);
          expect(control.x + control.width).toBeLessThanOrEqual(VIEWPORT_WIDTH - GUTTER);
        }
        expect(name.x, 'page gutter is 24px').toBeCloseTo(GUTTER, 0);

        expect(name.y + name.height).toBeLessThanOrEqual(email.y);
        expect(email.y + email.height).toBeLessThanOrEqual(message.y);
        expect(message.y + message.height).toBeLessThanOrEqual(button.y);
      });

      await test.step("Submit the empty form: errors are fully visible and 'Send message' is tappable", async () => {
        expect((await box(submitButton(page))).height).toBeGreaterThanOrEqual(44);
        await submit(page);
        for (const errorText of [NAME_ERROR, EMAIL_ERROR]) {
          const error = page.getByText(errorText, { exact: true });
          await expect(error).toBeVisible();
          await expect(error).toBeInViewport({ ratio: 1 });
          const b = await box(error);
          expect(b.x).toBeGreaterThanOrEqual(0);
          expect(b.x + b.width).toBeLessThanOrEqual(VIEWPORT_WIDTH);
          const clipped = await error.evaluate((el) => el.scrollWidth > el.clientWidth);
          expect(clipped, `'${errorText}' should not be clipped`).toBe(false);
        }
        await qa.expectNoHorizontalOverflow();
      });

      await test.step("Fill 'Name' and 'Email' and tap 'Send message'", async () => {
        await fillForm(page, NAME, EMAIL);
        await submit(page);

        await expect(heading(page, SENT_HEADING)).toBeVisible();
        const confirmation = page.getByText(THANKS, { exact: true });
        await expect(confirmation).toBeVisible();
        const b = await box(confirmation);
        expect(b.x).toBeGreaterThanOrEqual(0);
        expect(b.x + b.width).toBeLessThanOrEqual(VIEWPORT_WIDTH);
        const overflows = await confirmation.evaluate((el) => el.scrollWidth > el.clientWidth);
        expect(overflows, 'confirmation text should wrap without overflow').toBe(false);
        await qa.expectNoHorizontalOverflow();
      });
    },
  );

  test(
    'CONTACT-010: Header navigation collapses to a menu button on mobile',
    { tag: ['@responsive', '@contact', '@mobile', '@medium'] },
    async ({ page, qa }) => {
      const VIEWPORT_WIDTH = 390;
      const GUTTER = 24;
      const menuButton = page.getByRole('button', { name: 'Open menu' });

      await test.step('Open /contact at mobile viewport', async () => {
        await openContact(page);
      });

      await test.step("The 'Main' navigation is hidden and a 40x40 'Open menu' button is at the right", async () => {
        await expect(page.getByRole('link', { name: 'Demo Shop' })).toBeVisible();
        await expect(menuButton).toBeVisible();
        await expect(mainNav(page)).toBeHidden();

        const toggle = await box(menuButton);
        expect(toggle.width).toBe(40);
        expect(toggle.height).toBe(40);
        expect(VIEWPORT_WIDTH - (toggle.x + toggle.width), 'right gutter is 24px').toBeCloseTo(GUTTER, 0);
      });

      await test.step('Header is 64px high and does not overflow', async () => {
        const header = await box(page.getByRole('banner'));
        expect(header.height).toBe(64);
        await qa.expectNoHorizontalOverflow();
        const scrollWidth = await page.evaluate(() => document.documentElement.scrollWidth);
        expect(scrollWidth).toBe(VIEWPORT_WIDTH);
      });

      await test.step("Tap 'Open menu': all nav links are revealed", async () => {
        await menuButton.click();
        await expect(menuButton).toHaveAttribute('aria-expanded', 'true');
        await expect(mainNav(page)).toBeVisible();
        await expect(navLink(page, 'Home')).toBeVisible();
        await expect(mainNav(page).getByRole('link', { name: 'Shop all products', exact: true })).toBeVisible();
        await expect(mainNav(page).getByRole('link', { name: /^Checkout/ })).toBeVisible();
        await expect(navLink(page, 'Sign in to your account')).toBeVisible();
        await expect(navLink(page, 'Contact')).toBeVisible();
      });
    },
  );
});
